<script>
(()=>{const btn=document.getElementById('scanBtn'),video=document.getElementById('scanVideo'),input=document.getElementById('receiptCode');let stream=null,timer=null;async function stop(){if(timer)clearInterval(timer);if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;video.classList.remove('is-on');btn.textContent='Scan barcode';}btn?.addEventListener('click',async()=>{if(stream){stop();return;}if(!('BarcodeDetector' in window)){alert('Camera barcode scanning is not supported by this browser. You can still type or use a USB/Bluetooth barcode scanner.');return;}try{const formats=await BarcodeDetector.getSupportedFormats();const wanted=formats.includes('code_39')?['code_39']:formats;const det=new BarcodeDetector({formats:wanted});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;await video.play();video.classList.add('is-on');btn.textContent='Stop scanner';timer=setInterval(async()=>{try{const codes=await det.detect(video);if(codes[0]?.rawValue){input.value=codes[0].rawValue;await stop();input.form.submit();}}catch(e){}},450);}catch(e){alert('Camera could not be opened. You can still type or use a barcode scanner.');stop();}});})();
</script>
